package com.yongdrel.bulk_verification_service.application.service;
import com.fasterxml.jackson.databind.ObjectMapper; import com.yongdrel.bulk_verification_service.adapter.out.persistence.*; import com.yongdrel.bulk_verification_service.application.port.PaymentLookupPort; import org.junit.jupiter.api.*; import org.mockito.*; import org.springframework.mock.web.MockMultipartFile; import org.springframework.web.server.ResponseStatusException; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class BulkVerificationServiceTest{@Mock BatchRepository batches;@Mock ItemRepository items;@Mock PaymentLookupPort payments;BulkVerificationService service;UUID tenant=UUID.randomUUID(),org=UUID.randomUUID();
 @BeforeEach void setUp(){MockitoAnnotations.openMocks(this);service=new BulkVerificationService(batches,items,payments,new ObjectMapper());when(batches.save(any())).thenAnswer(x->x.getArgument(0));}
 @Test void matchesAndMarksDuplicateWithoutApproval(){when(payments.find("TX-1",tenant)).thenReturn(new PaymentLookupPort.PaymentMatch(UUID.randomUUID(),UUID.randomUUID(),tenant,true,true));var f=new MockMultipartFile("file","x.csv","text/csv","TX-1\nTX-1".getBytes());service.submit(tenant,org,"k",f);verify(items).save(argThat(i->i.getResult().name().equals("MATCHED")));verify(items).save(argThat(i->i.getResult().name().equals("DUPLICATE")));}
 @Test void idempotencyReturnsExistingBatch(){VerificationBatchEntity b=new VerificationBatchEntity(tenant,org,"k");when(batches.findByTenantIdAndIdempotencyKey(tenant,"k")).thenReturn(Optional.of(b));assertSame(b,service.submit(tenant,org,"k",new MockMultipartFile("file","x","text/csv","bad".getBytes())));verifyNoInteractions(payments);}
 @Test void unavailableDependencyRequiresReview(){when(payments.find("TX-1",tenant)).thenReturn(new PaymentLookupPort.PaymentMatch(null,null,tenant,false,false));service.submit(tenant,org,"k",new MockMultipartFile("file","x","text/csv","TX-1".getBytes()));verify(items).save(argThat(i->i.getResult().name().equals("REVIEW_REQUIRED")));}
 @Test void tenantCannotReadBatch(){VerificationBatchEntity b=new VerificationBatchEntity(tenant,org,"k");when(batches.findById(b.getId())).thenReturn(Optional.of(b));assertThrows(ResponseStatusException.class,()->service.results(b.getId(),UUID.randomUUID()));}}
